<?php
function csrf_token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function ui_icon($label){$paths=[
 'Active Products'=>'<path d="m12 3 8 4.5v9L12 21l-8-4.5v-9L12 3Z"/><path d="m4 7.5 8 4.5 8-4.5M12 12v9"/>',
 'Sellable Units'=>'<path d="M2 3h3l3 13h11l3-9H6"/><circle cx="9" cy="21" r="1"/><circle cx="18" cy="21" r="1"/>',
 'In Stock'=>'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v13c0 4 16 4 16 0V5M4 11c0 4 16 4 16 0"/>',
 'Low Stock'=>'<path d="M12 3 2 21h20L12 3Z"/><path d="M12 9v5m0 3v1"/>',
 'Out of Stock'=>'<circle cx="12" cy="12" r="10"/><path d="m5 19 14-14"/>',
 'Non-Sellable Units'=>'<path d="M3 3h8l10 10-8 8L3 11V3Z"/><circle cx="7" cy="7" r="1"/>',
 'Unmapped Items'=>'<path d="m9 15 6-6M8 12l-3 3a4 4 0 0 0 6 6l3-3m-6-6 3-3a4 4 0 0 1 6 6l-3 3"/>',
 ];return '<svg class="ui-icon" width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$label]??$paths['Active Products']).'</svg>';}
function verify_csrf(){if(!hash_equals(csrf_token(),(string)($_POST['csrf']??'')))throw new Exception('This form expired. Refresh the page and try again.');}
function whole_number($value,$label='Quantity',$min=0){$v=trim((string)$value);if(!preg_match('/^\d+$/D',$v)||strlen($v)>10||(float)$v>2147483647||(int)$v<$min)throw new Exception($label.' must be a whole number between '.$min.' and 2147483647.');return (int)$v;}
function receipt_quantity($source,$uom){if(!is_numeric($source)||(float)$source<=0)throw new Exception('Shipped quantity must be greater than zero.');$factor=receipt_uom_factor($uom);if($factor===null)throw new Exception('UOM must be pc or bx(n) with a positive box size.');$value=(float)$source*$factor;if(!is_finite($value)||$value>2147483647||abs($value-round($value))>0.000001)throw new Exception('Converted quantity must be a positive whole number of pieces.');return [$factor,(int)round($value)];}
function active_product($id){$st=db()->prepare('SELECT * FROM products WHERE id=? AND active=1');$st->execute([(int)$id]);$r=$st->fetch();if(!$r)throw new Exception('Select an active Product Master item.');return $r;}
function validate_user_role($role){if(!in_array($role,access_role_names(),true))throw new Exception('Invalid user role.');}
function guard_last_admin($id,$role=null,$active=null){$st=db()->prepare('SELECT * FROM users WHERE id=? FOR UPDATE');$st->execute([$id]);$r=$st->fetch();if(!$r)throw new Exception('User not found.');if($r['role']==='Admin'&&(int)$r['active']===1&&(($role!==null&&$role!=='Admin')||$active===0)){if((int)db()->query("SELECT COUNT(*) FROM users WHERE role='Admin' AND active=1")->fetchColumn()<=1)throw new Exception('Keep at least one active administrator.');}}
function stock_status_key($label){return ['In Stock'=>'in','Low Stock'=>'low','Out of Stock'=>'out','Reconcile'=>'negative'][$label]??'';}
function history_pages(){return ['beginning','inflow','outflow','nonsellable','allocation','allocation_history','transfers','file_generator','imports','receipts','reconciliation','activity'];}
function history_sql($sql){global $page;$sql=inventory_filter_sql($sql);if(!in_array($page??'',history_pages(),true))return $sql;if(!preg_match('/LIMIT\s+(\d+)\s*$/i',$sql,$m)||(int)$m[1]<100)return $sql;if(!str_contains($sql,'?'))$GLOBALS['rs8_history_total']=rs8_list_total('SELECT COUNT(*) FROM ('.preg_replace('/LIMIT\s+\d+\s*$/i','',$sql).') rs8_history_rows');$all=($_GET['history']??'')==='all';$offset=$all?max(0,min(100000,(int)($_GET['offset']??0))):0;return preg_replace('/LIMIT\s+\d+\s*$/i','LIMIT '.($all?50:10).' OFFSET '.$offset,$sql);}
function history_controls($page){if($page==='imports')return;if(in_array($page,['beginning','file_generator','receipts','allocation_history','outflow','nonsellable','transfers','reconciliation'],true)){compact_history_controls($page);return;}if(!in_array($page,history_pages(),true))return;$args=['page'=>$page];foreach(['brand','main_category','subcategory','q','status'] as $filterKey)if(isset($_GET[$filterKey])&&is_string($_GET[$filterKey]))$args[$filterKey]=$_GET[$filterKey];if(isset($_GET['platform']))$args['platform']=$_GET['platform'];$base='?'.http_build_query($args);$all=($_GET['history']??'')==='all';$offset=max(0,(int)($_GET['offset']??0));echo '<div class="tabs history-tabs"><a class="tab '.(!$all?'active':'').'" href="'.e($base).'">Latest 10</a><a class="tab '.($all?'active':'').'" href="'.e($base.'&history=all').'">History</a>';echo '</div>';}
function release_total($id){$q=db()->prepare('SELECT COALESCE(SUM(qty),0) FROM nonsellable_release_links WHERE non_sellable_id=?');$q->execute([$id]);return (int)$q->fetchColumn();}
function nonsellable_source_options(){$html='';foreach(db()->query('SELECT n.*,p.name,p.master_sku,p.brand FROM non_sellable n JOIN products p ON p.id=n.product_id ORDER BY n.id DESC') as $r){$remaining=(int)$r['qty']-release_total($r['id']);if($remaining>0)$html.='<option value="'.(int)$r['id'].'">'.e('NS-'.$r['id'].' · '.$r['name'].' · '.$r['brand'].' · '.$r['master_sku'].' · '.$r['order_id'].' · '.$remaining.' pcs before legacy releases').'</option>';}return $html;}
function record_nonsellable_release($source,$pid,$qty,$data,$uid){if(in_array(($data['type']??''),['Ready for Sale','Repackaging Reclassification'],true))throw new Exception('Use Admin Ready for Sale approval to preserve physical stock and allocation.');$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM non_sellable WHERE id=? FOR UPDATE');$q->execute([$source]);$r=$q->fetch();if(!$r||(int)$r['product_id']!==$pid)throw new Exception('Select the original non-sellable record for this product.');$remaining=(int)$r['qty']-release_total($source);$stock=stock_row($pid);if($qty<=0||$qty>$remaining||$qty>$stock['nonsellable'])throw new Exception('Release exceeds the original record remaining quantity or physical non-sellable balance.');$pdo->prepare('INSERT INTO nonsellable_outflows(txn_date,product_id,qty,type,reference_no,remarks,user_id) VALUES(?,?,?,?,?,?,?)')->execute([$data['txn_date'],$pid,$qty,$data['type'],trim($data['reference_no']??''),trim($data['remarks']??''),$uid]);$release=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO nonsellable_release_links(release_id,non_sellable_id,qty) VALUES(?,?,?)')->execute([$release,$source,$qty]);audit('Non-sellable outflow','Non-Sellable','NS-'.$source,$qty.' pcs; release #'.$release);$pdo->commit();return $release;}catch(Throwable $e){$pdo->rollBack();throw $e;}}
function threshold_file_rows($file){$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));if($ext==='xlsx')return XlsxReader::rows($file['tmp_name']);if($ext!=='csv')throw new Exception('Upload a CSV or XLSX threshold file.');$f=fopen($file['tmp_name'],'r');$rows=[];while(($row=fgetcsv($f))!==false)$rows[]=$row;fclose($f);if($rows)$rows[0][0]=preg_replace('/^\xEF\xBB\xBF/','',$rows[0][0]);return $rows;}
function validate_threshold_rows($rows){
 $hr=find_header_row($rows,[['master sku','low stock threshold'],['master sku','low_stock_threshold']]);if($hr===null)throw new Exception('Required columns: Master SKU and Low Stock Threshold.');
 $h=array_map('norm',$rows[$hr]);$si=array_search('master sku',$h,true);$qi=array_search('low stock threshold',$h,true);if($qi===false)$qi=array_search('low_stock_threshold',$h,true);
 $lines=[];$errors=[];$seen=[];$query=db()->prepare('SELECT id,name,master_sku,COALESCE(low_stock_threshold,10) threshold FROM products WHERE master_sku=? AND active=1');
 foreach(array_slice($rows,$hr+1) as $i=>$row){if(!array_filter($row,fn($v)=>trim((string)$v)!==''))continue;$rn=$hr+$i+2;try{$sku=trim($row[$si]??'');if($sku==='')throw new Exception('Master SKU is required.');$key=product_code_lookup($sku)?:strtolower($sku);if(isset($seen[$key]))throw new Exception('Duplicate Master SKU: '.$sku);$seen[$key]=true;$new=whole_number($row[$qi]??'','Low Stock Threshold');$query->execute([$sku]);$p=$query->fetch();if(!$p&&($mapped=product_code_lookup($sku))){$query->execute([active_product($mapped)['master_sku']]);$p=$query->fetch();}if(!$p)throw new Exception('Unknown or inactive Master SKU: '.$sku);$lines[]=['product_id'=>(int)$p['id'],'master_sku'=>$p['master_sku'],'product_name'=>$p['name'],'old_threshold'=>(int)$p['threshold'],'new_threshold'=>$new];}catch(Throwable $e){$errors[]='Row '.$rn.': '.$e->getMessage();}}
 if(!$lines&&!$errors)$errors[]='No product rows found.';return [$lines,$errors];
}
function stage_threshold_upload($file,$uid){[$lines,$errors]=validate_threshold_rows(threshold_file_rows($file));$pdo=db();$pdo->beginTransaction();try{$ref=next_ref('THR');$pdo->prepare('INSERT INTO threshold_batches(batch_ref,filename,status,row_count,error_json,user_id) VALUES(?,?,?,?,?,?)')->execute([$ref,basename($file['name']),$errors?'Unsuccessful':'To Review',count($lines),json_encode($errors),$uid]);$id=(int)$pdo->lastInsertId();$st=$pdo->prepare('INSERT INTO threshold_lines(batch_id,product_id,master_sku,product_name,old_threshold,new_threshold) VALUES(?,?,?,?,?,?)');foreach($lines as $r)$st->execute([$id,$r['product_id'],$r['master_sku'],$r['product_name'],$r['old_threshold'],$r['new_threshold']]);audit('Validate thresholds','Threshold Batch',$ref,count($lines).' rows; '.count($errors).' errors');$pdo->commit();return [$id,$errors];}catch(Throwable $e){$pdo->rollBack();throw $e;}}
function confirm_threshold_batch($id){$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM threshold_batches WHERE id=? FOR UPDATE');$q->execute([$id]);$b=$q->fetch();if(!$b||$b['status']!=='To Review')throw new Exception('This threshold batch is not pending confirmation.');$q=$pdo->prepare('SELECT * FROM threshold_lines WHERE batch_id=? ORDER BY product_id');$q->execute([$id]);$rows=$q->fetchAll();if(!$rows)throw new Exception('No threshold rows.');$check=$pdo->prepare('SELECT active,COALESCE(low_stock_threshold,10) threshold FROM products WHERE id=? FOR UPDATE');$save=$pdo->prepare('UPDATE products SET low_stock_threshold=? WHERE id=?');foreach($rows as $r){$check->execute([$r['product_id']]);$p=$check->fetch();if(!$p||!$p['active']||(int)$p['threshold']!==(int)$r['old_threshold'])throw new Exception('Product '.$r['master_sku'].' changed since preview. Download and upload a fresh file. No thresholds were changed.');$save->execute([$r['new_threshold'],$r['product_id']]);}$pdo->prepare("UPDATE threshold_batches SET status='Confirmed',confirmed_at=CURRENT_TIMESTAMP WHERE id=?")->execute([$id]);audit('Confirm thresholds','Threshold Batch',$b['batch_ref'],count($rows).' thresholds updated. Stock quantities unchanged.');$pdo->commit();return count($rows);}catch(Throwable $e){$pdo->rollBack();throw $e;}}
function confirm_receipt_batch($bid,$uid){
 $pdo=db();$pdo->beginTransaction();try{
  $q=$pdo->prepare('SELECT * FROM inflow_batches WHERE id=? FOR UPDATE');$q->execute([$bid]);$b=$q->fetch();if(!$b||$b['batch_type']!=='Receipt PDF'||$b['status']!=='To Review')throw new Exception('This receipt is not pending confirmation. Confirmed receipts cannot be posted again.');
  $q=$pdo->prepare('SELECT COUNT(*) FROM inflows WHERE batch_id=?');$q->execute([$bid]);if($q->fetchColumn())throw new Exception('This receipt already has posted inventory.');
  $q=$pdo->prepare('SELECT * FROM receipt_staging_lines WHERE batch_id=? ORDER BY line_no FOR UPDATE');$q->execute([$bid]);$rows=$q->fetchAll();if(!$rows)throw new Exception('No receipt lines are available.');$allocation=checked_incoming_allocation($b);inflow_duplicate_review($b,true);$total=0;
  $ins=$pdo->prepare('INSERT INTO inflows(batch_id,txn_date,reference_no,source_name,source_platform,product_id,source_qty,source_uom,conversion_factor,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');
  foreach($rows as $r){active_product($r['product_id']);[$factor,$qty]=receipt_quantity($r['source_qty'],$r['source_uom']);if($r['validation_status']!=='Matched'||$factor!==(int)$r['conversion_factor']||$qty!==(int)$r['final_qty'])throw new Exception('Every receipt line must have a validated product, quantity and UOM.');$ins->execute([$bid,$b['txn_date'],$b['reference_no'],$b['source_name'],'',$r['product_id'],$r['source_qty'],$r['source_uom'],$factor,$qty,'Receipt Delivery','',$uid]);$total+=$qty;}
  post_incoming_allocation($b,$allocation,$uid);$pdo->prepare("UPDATE inflow_batches SET status='Confirmed',total_qty=?,error_count=0,error_json=NULL WHERE id=?")->execute([$total,$bid]);audit('Confirm receipt inflow','Receipt',$b['reference_no'],count($rows).' lines / '.$total.' pcs');$pdo->commit();return [count($rows),$total];
 }catch(Throwable $e){$pdo->rollBack();throw $e;}
}
function update_receipt_line($line,$pid,$source,$uom){$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT batch_id FROM receipt_staging_lines WHERE id=?');$q->execute([$line]);$bid=$q->fetchColumn();if(!$bid)throw new Exception('Receipt line not found.');$q=$pdo->prepare('SELECT * FROM inflow_batches WHERE id=? FOR UPDATE');$q->execute([$bid]);$b=$q->fetch();if(!$b||$b['status']!=='To Review')throw new Exception('Only pending receipts can be corrected.');active_product($pid);[$factor,$qty]=receipt_quantity($source,$uom);$pdo->prepare("UPDATE receipt_staging_lines SET product_id=?,source_qty=?,source_uom=?,conversion_factor=?,final_qty=?,validation_status='Matched',validation_message='' WHERE id=?")->execute([$pid,$source,$uom,$factor,$qty,$line]);if(!empty($_POST['save_alias'])){$q=$pdo->prepare('SELECT raw_item FROM receipt_staging_lines WHERE id=?');$q->execute([$line]);$raw=$q->fetchColumn();if(trim($raw)!=='')$pdo->prepare('INSERT INTO receipt_aliases(normalized_alias,alias,product_id) VALUES(?,?,?) ON DUPLICATE KEY UPDATE product_id=VALUES(product_id)')->execute([norm($raw),$raw,$pid]);}audit('Correct receipt line','Receipt',$b['batch_ref'],'Line #'.$line.' validated by reviewer');$pdo->commit();return $bid;}catch(Throwable $e){$pdo->rollBack();throw $e;}}

function platform_label($platform){
 $files=['Lazada'=>'lazada.svg','Shopee'=>'shopee.svg','TikTok'=>'tiktok.svg'];
 if(!isset($files[$platform]))return e($platform);
 return '<span class="platform-brand"><img src="assets/logos/'.$files[$platform].'" alt="'.e($platform).'" width="88" height="28"></span>';
}
function platform_logos(){return '<span class="platform-cluster">'.platform_label('Lazada').platform_label('Shopee').platform_label('TikTok').'</span>';}
